<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function nekoko_core_profile_submit() {
	if ( empty( $_POST['nekoko_profile_form'] ) ) { return; } nekoko_core_require_login(); $id = get_current_user_id(); if ( ! wp_verify_nonce( $_POST['_wpnonce'] ?? '', 'nekoko_profile_form' ) ) { wp_die( 'Nevažeći zahtev.', 403 ); }
	$errors = new WP_Error(); $user = get_userdata( $id ); $first = sanitize_text_field( wp_unslash( $_POST['first_name'] ?? '' ) ); $last = sanitize_text_field( wp_unslash( $_POST['last_name'] ?? '' ) ); $display = sanitize_text_field( wp_unslash( $_POST['display_name'] ?? '' ) ); $email = sanitize_email( wp_unslash( $_POST['user_email'] ?? '' ) );
	if ( ! $first || ! $last || ! $display ) { $errors->add( 'required', 'Ime, prezime i prikazano ime su obavezni.' ); } if ( ! is_email( $email ) ) { $errors->add( 'email', 'Unesite ispravnu email adresu.' ); } elseif ( email_exists( $email ) && (int) email_exists( $email ) !== $id ) { $errors->add( 'email_taken', 'Ovu email adresu već koristi drugi nalog.' ); }
	if ( $email !== $user->user_email && ! wp_check_password( (string) ( $_POST['current_password'] ?? '' ), $user->user_pass, $id ) ) { $errors->add( 'current_password', 'Trenutna lozinka nije ispravna.' ); }
	if ( $errors->has_errors() ) { set_transient( 'nekoko_profile_errors_' . $id, $errors, MINUTE_IN_SECONDS ); wp_safe_redirect( nekoko_core_page_url( 'moj-profil' ) ); exit; }
	wp_update_user( array( 'ID' => $id, 'first_name' => $first, 'last_name' => $last, 'display_name' => $display ) ); foreach ( array( 'nekoko_phone', 'nekoko_city' ) as $field ) { update_user_meta( $id, $field, sanitize_text_field( wp_unslash( $_POST[ $field ] ?? '' ) ) ); } update_user_meta( $id, 'nekoko_profile_bio', sanitize_textarea_field( wp_unslash( $_POST['nekoko_profile_bio'] ?? '' ) ) ); update_user_meta( $id, 'nekoko_show_phone', ! empty( $_POST['nekoko_show_phone'] ) ? '1' : '0' );
	if ( $email !== $user->user_email ) { update_user_meta( $id, 'nekoko_pending_email', $email ); nekoko_core_issue_verification( $id, 'email_change', $email ); set_transient( 'nekoko_profile_notice_' . $id, 'Poslali smo link za potvrdu na novu email adresu. Vaša trenutna email adresa ostaje aktivna dok ne potvrdite novu.', MINUTE_IN_SECONDS ); } else { set_transient( 'nekoko_profile_notice_' . $id, 'Profil je uspešno sačuvan.', MINUTE_IN_SECONDS ); }
	wp_safe_redirect( nekoko_core_page_url( 'moj-profil' ) ); exit;
}
add_action( 'template_redirect', 'nekoko_core_profile_submit', 8 );
function nekoko_core_profile_password_submit() { if ( empty( $_POST['nekoko_profile_password'] ) ) { return; } nekoko_core_require_login(); $id = get_current_user_id(); $user = get_userdata( $id ); if ( ! wp_verify_nonce( $_POST['_wpnonce'] ?? '', 'nekoko_profile_password' ) || ! wp_check_password( (string) ( $_POST['current_password'] ?? '' ), $user->user_pass, $id ) ) { set_transient( 'nekoko_profile_password_error_' . $id, 'Trenutna lozinka nije ispravna.', MINUTE_IN_SECONDS ); } elseif ( $_POST['new_password'] !== $_POST['new_password_repeat'] || ! nekoko_core_password_is_strong( $_POST['new_password'] ?? '' ) ) { set_transient( 'nekoko_profile_password_error_' . $id, 'Nova lozinka mora imati najmanje 10 karaktera, slovo i broj, a oba unosa moraju biti ista.', MINUTE_IN_SECONDS ); } else { wp_set_password( $_POST['new_password'], $id ); wp_set_auth_cookie( $id, true ); set_transient( 'nekoko_profile_notice_' . $id, 'Lozinka je uspešno promenjena.', MINUTE_IN_SECONDS ); } wp_safe_redirect( nekoko_core_page_url( 'moj-profil' ) ); exit; }
add_action( 'template_redirect', 'nekoko_core_profile_password_submit', 9 );
function nekoko_core_cancel_email_change() { if ( empty( $_GET['nekoko_cancel_email'] ) || ! is_user_logged_in() || ! wp_verify_nonce( $_GET['_wpnonce'] ?? '', 'nekoko_cancel_email' ) ) { return; } $id = get_current_user_id(); foreach ( array( 'nekoko_pending_email', 'nekoko_email_change_token_hash', 'nekoko_email_change_expires' ) as $key ) { delete_user_meta( $id, $key ); } set_transient( 'nekoko_profile_notice_' . $id, 'Promena email adrese je otkazana.', MINUTE_IN_SECONDS ); wp_safe_redirect( nekoko_core_page_url( 'moj-profil' ) ); exit; }
add_action( 'template_redirect', 'nekoko_core_cancel_email_change', 10 );
function nekoko_core_shortcode_profile() { nekoko_core_require_login(); return nekoko_core_template( 'profile-form' ); }
add_shortcode( 'nekoko_profile_form', 'nekoko_core_shortcode_profile' );
